    /**
     * Devuelve el markup <svg> de un icono. En local/testing revienta si el
     * nombre no está en el catálogo (para pescar typos o nombres de otra
     * librería —p. ej. Heroicons— antes de que lleguen a producción); en
     * producción cae al icono por defecto para no romper la página por esto.
     */
    public static function svg(string $nombre, string $clases = 'h-5 w-5 shrink-0', array $atributos = []): string
    {
        if (! isset(self::TRAZOS[$nombre]) && app()->environment(['local', 'testing'])) {
            throw new \InvalidArgumentException("Icono '{$nombre}' no existe en Iconos::TRAZOS.");
        }

        $trazo = self::TRAZOS[$nombre] ?? self::TRAZOS[self::POR_DEFECTO];

        $svg = array_merge([
            'xmlns' => 'http://www.w3.org/2000/svg',
            'viewBox' => '0 0 24 24',
            'fill' => 'none',
            'stroke' => 'currentColor',
            'stroke-width' => '2',
            'stroke-linecap' => 'round',
            'stroke-linejoin' => 'round',
            'class' => trim($clases),
            'aria-hidden' => 'true',
            'focusable' => 'false',
        ], $atributos);

        if (isset($atributos['aria-label'])) {
            unset($svg['aria-hidden']);
            $svg['role'] = 'img';
        }

        $html = '<svg';
        foreach ($svg as $clave => $valor) {
            if ($valor === null || $valor === false) {
                continue;
            }
            $html .= ' '.$clave.'="'.htmlspecialchars((string) $valor, ENT_QUOTES, 'UTF-8').'"';
        }

        return $html.'>'.$trazo.'</svg>';
    }

    // Icono correspondiente a cada tipo de mensaje flash
    public static function paraFlash(string $tipo): string
    {
        return match ($tipo) {
            'success' => 'circle-check',
            'warning' => 'triangle-alert',
            'error' => 'circle-x',
            default => 'circle-help',
        };
    }
}
